package main

const leaderboardAdminHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>leqra leaderboard</title><link rel="stylesheet" href="/admin.css"><script src="/admin.js" defer></script></head>
<body><main><header><a href="/">leqra</a><span>Public Infinity leaderboard</span></header>
<p class="muted">Local administration. Changes are saved immediately and sent to connected public players.</p>
<section class="controls"><label for="pattern">Match callsigns with a regular expression</label><div class="row"><input id="pattern" type="text" placeholder="e.g. (?i)^test" autocomplete="off" spellcheck="false" maxlength="1024"><button id="refresh" type="button">Refresh</button></div><p class="muted">Uses Go regular expressions. An empty pattern previews everyone.</p><div class="row"><button id="remove" class="danger" type="button" disabled>Clear matches</button><button id="reset" class="danger" type="button">Reset all</button></div><p class="muted">Clearing removes offline entries and sets affected connected players to 0. They stay in the game.</p></section>
<p id="status" role="status" aria-live="polite">Loading…</p><p id="counts" class="muted"></p><div class="table"><table><thead><tr><th>Callsign</th><th>Score</th><th>Kind</th><th>Status</th></tr></thead><tbody id="entries"></tbody></table></div>
</main></body></html>`

const leaderboardAdminCSS = `:root{color-scheme:dark;font:14px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;background:#0c111c;color:#e6edf8}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:auto;padding:28px 20px}header{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:18px}header a{font-size:30px;font-weight:bold;color:#f4cb6b;text-decoration:none}header span{font-size:18px}.muted{color:#a7b6cb}.controls{border:1px solid #33415a;background:#121c2c;padding:20px;border-radius:8px;margin-top:24px}label{display:block;margin-bottom:8px;font-weight:bold}.row{display:flex;gap:12px;flex-wrap:wrap}input,button{font:inherit;border:1px solid #4c6283;border-radius:5px;padding:10px 14px;background:#17253c;color:inherit}input{flex:1;min-width:160px}button{cursor:pointer}button:hover{background:#263d5e}button:disabled{opacity:.5;cursor:default}.danger{border-color:#ba686e}.danger:hover{background:#542c38}:focus-visible{outline:2px solid #f4cb6b;outline-offset:3px}#status{min-height:24px;color:#f4cb6b}.table{overflow:auto}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #27364e;overflow-wrap:anywhere}th:first-child{width:42%}th:nth-child(2){width:14%}th:nth-child(3){width:16%}th:nth-child(4){width:28%}th{color:#a7b6cb;font-size:12px}td:nth-child(2){font-variant-numeric:tabular-nums}@media(max-width:500px){main{padding:18px 12px}.controls{padding:14px}th,td{padding:10px 5px;font-size:12px}}`

const leaderboardAdminJS = `"use strict";
const pattern=document.querySelector('#pattern'),remove=document.querySelector('#remove'),reset=document.querySelector('#reset'),status=document.querySelector('#status'),counts=document.querySelector('#counts'),entries=document.querySelector('#entries');
let csrf='',matched=0,busy=false,revision=0,timer,validatedPattern=null;
function canRemove(){return !busy&&!!csrf&&!!pattern.value&&validatedPattern===pattern.value&&matched>0}
async function load(){const rev=++revision,query=pattern.value;validatedPattern=null;matched=0;remove.disabled=true;try{const response=await fetch('/api/leaderboard?pattern='+encodeURIComponent(query),{cache:'no-store'});if(!response.ok)throw new Error(await response.text());const data=await response.json();if(rev!==revision)return;csrf=data.csrfToken;matched=data.matched;validatedPattern=query;counts.textContent=data.total+' entries, '+data.connected+' connected, '+matched+' matches'+(matched>data.entries.length?' (showing first '+data.entries.length+')':'');entries.replaceChildren();for(const entry of data.entries){const row=document.createElement('tr');for(const value of [entry.name,String(entry.score),entry.bot?'Bot':'Player',entry.connected?'Connected':'Offline']){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}entries.append(row)}status.textContent='';remove.disabled=!canRemove()}catch(error){if(rev!==revision)return;status.textContent=error.message;counts.textContent='';entries.replaceChildren()}}
async function change(path,body,message){if(busy||!csrf||path==='/api/remove'&&!canRemove()||!confirm(message))return;busy=true;revision++;remove.disabled=true;reset.disabled=true;try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Leqra-Admin-CSRF':csrf},body:JSON.stringify(body)});if(!response.ok)throw new Error(await response.text());const data=await response.json();await load();status.textContent='Leaderboard updated. '+data.affected+' entries affected.'}catch(error){status.textContent=error.message}finally{busy=false;reset.disabled=false;remove.disabled=!canRemove()}}
pattern.addEventListener('input',()=>{clearTimeout(timer);revision++;validatedPattern=null;matched=0;remove.disabled=true;timer=setTimeout(load,250)});document.querySelector('#refresh').addEventListener('click',load);reset.addEventListener('click',()=>change('/api/reset',{},'Reset the entire Public Infinity leaderboard? All connected players will continue at score 0.'));remove.addEventListener('click',()=>change('/api/remove',{pattern:pattern.value},'Clear '+matched+' matching entries? Affected connected players will continue at score 0.'));load();setInterval(()=>{if(!busy&&!document.hidden)load()},5000);`
